// One-off smoke test: serve the repo, load demo.html in headless Chrome via CDP,
// assert the 5 boards render with no page errors, then resize #board-1's wrap and
// assert the ResizeObserver-driven relayout happened.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import path from 'node:path';
import os from 'node:os';

const ROOT = 'D:/dev/ab-tasks/chessground-qwen-med-r1';
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const PORT = 8471;
const CDP_PORT = 9333;
const MIME = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
};

const failures = [];
const check = (name, ok, detail) => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  [' + detail + ']' : ''}`);
  if (!ok) failures.push(name);
};

// --- static server
const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  const p = path.join(ROOT, decodeURIComponent(url.pathname));
  try {
    const data = await readFile(p);
    res.writeHead(200, { 'content-type': MIME[path.extname(p)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404, { 'content-type': 'text/plain' });
    res.end('not found: ' + p);
  }
});
await new Promise(r => server.listen(PORT, '127.0.0.1', r));

// --- headless Chrome
const profile = await import('node:fs/promises').then(m => m.mkdtemp(path.join(os.tmpdir(), 'cg-chrome-')));
const chrome = spawn(
  CHROME,
  ['--headless=new', '--no-first-run', '--no-default-browser-check', '--disable-gpu', `--remote-debugging-port=${CDP_PORT}`, `--user-data-dir=${profile}`, 'about:blank'],
  { stdio: 'ignore' },
);
try {
  let up = false;
  for (let i = 0; i < 50 && !up; i++) {
    try {
      await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/version`)).json();
      up = true;
    } catch {
      await sleep(200);
    }
  }
  if (!up) throw new Error('chrome did not start');

  const tab = await (
    await fetch(`http://127.0.0.1:${CDP_PORT}/json/new?about:blank`, { method: 'PUT' })
  ).json();
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((r, j) => {
    ws.onopen = r;
    ws.onerror = () => j(new Error('ws connect failed'));
  });

  let id = 0;
  const pending = new Map();
  const events = new Set();
  const pageErrors = [];
  ws.onmessage = m => {
    const msg = JSON.parse(m.data);
    if (msg.id) {
      pending.get(msg.id)?.(msg);
      pending.delete(msg.id);
    } else if (msg.method) {
      events.add(msg.method);
      if (msg.method === 'Runtime.exceptionThrown') pageErrors.push(JSON.stringify(msg.params.exceptionDetails));
      if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error')
        pageErrors.push(msg.params.args.map(a => a.value ?? a.description ?? '').join(' '));
      if (msg.method === 'Log.entryAdded' && msg.params.entry.level === 'error') pageErrors.push(msg.params.entry.text);
    }
  };
  const send = (method, params = {}) =>
    new Promise(r => {
      const i = ++id;
      pending.set(i, r);
      ws.send(JSON.stringify({ id: i, method, params }));
    });
  const evalJs = async expr =>
    (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result.value;

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.navigate', { url: `http://127.0.0.1:${PORT}/demo.html` });
  for (let i = 0; i < 100 && !events.has('Page.loadEventFired'); i++) await sleep(100);
  check('page load event fired', events.has('Page.loadEventFired'));
  await sleep(300); // let module script + RO settle

  // --- load assertions
  const boards = await evalJs(`document.querySelectorAll('cg-board').length`);
  check('5 cg-board elements rendered', boards === 5, `got ${boards}`);
  const squares = await evalJs(`document.querySelectorAll('#board-1 square').length`);
  check('64 squares in board-1', squares === 64, `got ${squares}`);
  const fen2 = await evalJs(`document.querySelector('#board-2 .piece.wN') !== null`);
  check('fen board-2 shows white knight on d5', fen2 === true);
  check('no page/console errors', pageErrors.length === 0, pageErrors.join(' | '));

  // --- resize assertions
  const before = await evalJs(
    `(() => {
      const c = document.querySelector('#board-1 cg-container');
      const sq = document.querySelector('#board-1 square');
      return { style: c.style.width, rect: c.getBoundingClientRect().width, sq: sq.getBoundingClientRect().width };
    })()`,
  );
  check('initial container 500px', before.style === '500px' && before.rect === 500, JSON.stringify(before));
  check('initial square ~62.5px', Math.abs(before.sq - 62.5) < 0.01, `got ${before.sq}`);

  await evalJs(`document.getElementById('board-1').style.cssText += ';width:300px;height:300px'; 'ok'`);
  await sleep(500); // ResizeObserver is async; allow a few frames

  const after = await evalJs(
    `(() => {
      const c = document.querySelector('#board-1 cg-container');
      const sq = document.querySelector('#board-1 square');
      return { style: c.style.width, styleH: c.style.height, rect: c.getBoundingClientRect().width, sq: sq.getBoundingClientRect().width };
    })()`,
  );
  check('after resize container style 300x300', after.style === '300px' && after.styleH === '300px', JSON.stringify(after));
  check('after resize container rect 300px', after.rect === 300, `got ${after.rect}`);
  check('after resize square ~37.5px', Math.abs(after.sq - 37.5) < 0.01, `got ${after.sq}`);

  // other boards untouched by #board-1 resize
  const b2 = await evalJs(`document.querySelector('#board-2 cg-container').style.width`);
  check('board-2 unaffected (still 500px)', b2 === '500px', `got ${b2}`);

  check('no page/console errors after resize', pageErrors.length === 0, pageErrors.join(' | '));

  ws.close();
} finally {
  chrome.kill('SIGTERM');
  server.close();
}

if (failures.length) {
  console.error(`\n${failures.length} check(s) FAILED`);
  process.exit(1);
}
console.log('\nAll demo checks passed.');
process.exit(0);

