1:import * as drag from './drag.js';
2:import * as draw from './draw.js';
3:import { drop } from './drop.js';
4:import { type State } from './state.js';
5:import type * as cg from './types.js';
6:import { isRightButton } from './util.js';
7:
8:type MouchBind = (e: cg.MouchEvent) => void;
9:type StateMouchBind = (d: State, e: cg.MouchEvent) => void;
10:
11:export function bindBoard(s: State, onResize: () => void): void {
12:  const boardEl = s.dom.elements.board;
13:
14:  if ('ResizeObserver' in window) {
15:    s.dom.ro = new ResizeObserver(onResize);
16:    s.dom.ro.observe(s.dom.elements.wrap);
17:  }
18:
19:  if (s.disableContextMenu || s.drawable.enabled) {
20:    boardEl.addEventListener('contextmenu', e => e.preventDefault());
21:  }
22:
23:  if (s.viewOnly) return;
24:
25:  // Cannot be passive, because we prevent touch scrolling and dragging of
26:  // selected elements.
27:  const onStart = startDragOrDraw(s);
28:  boardEl.addEventListener('touchstart', onStart as EventListener, {
29:    passive: false,
30:  });
31:  boardEl.addEventListener('mousedown', onStart as EventListener, {
32:    passive: false,
33:  });
34:}
35:
36:// returns the unbind function
37:export function bindDocument(s: State, onResize: () => void): cg.Unbind {
38:  const unbinds: cg.Unbind[] = [];
39:
40:  // Old versions of Edge and Safari do not support ResizeObserver. Send
41:  // chessground.resize if a user action has changed the bounds of the board.
42:  if (!('ResizeObserver' in window)) unbinds.push(unbindable(document.body, 'chessground.resize', onResize));
43:
44:  if (!s.viewOnly) {
45:    const onmove = dragOrDraw(s, drag.move, draw.move);
46:    const onend = dragOrDraw(s, drag.end, draw.end);
47:
48:    for (const ev of ['touchmove', 'mousemove'])
49:      unbinds.push(unbindable(document, ev, onmove as EventListener));
50:    for (const ev of ['touchend', 'mouseup']) unbinds.push(unbindable(document, ev, onend as EventListener));
51:
52:    const onScroll = () => s.dom.bounds.clear();
53:    unbinds.push(unbindable(document, 'scroll', onScroll, { capture: true, passive: true }));
54:    unbinds.push(unbindable(window, 'resize', onScroll, { passive: true }));
55:  }
56:
57:  return () => unbinds.forEach(f => f());
58:}
59:
60:function unbindable(
61:  el: EventTarget,
62:  eventName: string,
63:  callback: EventListener,
64:  options?: AddEventListenerOptions,
65:): cg.Unbind {
66:  el.addEventListener(eventName, callback, options);
67:  return () => el.removeEventListener(eventName, callback, options);
68:}
69:
70:const startDragOrDraw =
71:  (s: State): MouchBind =>
72:  e => {
73:    if (s.draggable.current) drag.cancel(s);
74:    else if (s.drawable.current) draw.cancel(s);
75:    else if (e.shiftKey || isRightButton(e)) {
76:      if (s.drawable.enabled) draw.start(s, e);
77:    } else if (!s.viewOnly) {
78:      if (s.dropmode.active) drop(s, e);
79:      else drag.start(s, e);
80:    }
81:  };
82:
83:const dragOrDraw =
84:  (s: State, withDrag: StateMouchBind, withDraw: StateMouchBind): MouchBind =>
85:  e => {
