// One-off: prove (a) the old cg-board subtree (with its bindBoard listeners) is
// collectible after redrawAll while the instance stays alive, and (b) the wrap
// subtree is collectible after destroy, using a ResizeObserver fake with
// real-controller semantics (a global registry retains observers until disconnect()).
import { JSDOM } from 'jsdom';

const dom = new JSDOM('<!doctype html><html><body></body></html>', { url: 'http://localhost/' });
const { window } = dom;

// browser-faithful RO: global controller retains observers until disconnect
class FakeRO {
  static registry = [];
  constructor(cb) {
    this.cb = cb;
    FakeRO.registry.push(this);
  }
  observe(el) {
    this.el = el;
  }
  unobserve() {}
  disconnect() {
    this.cb = null;
    this.el = null;
    const i = FakeRO.registry.indexOf(this);
    if (i >= 0) FakeRO.registry.splice(i, 1);
  }
}
window.ResizeObserver = FakeRO;

globalThis.window = window;
globalThis.document = window.document;
globalThis.HTMLElement = window.HTMLElement;
globalThis.navigator = window.navigator;
globalThis.requestAnimationFrame = cb => setTimeout(cb, 0);

const { Chessground } = await import('./dist/chessground.js');

const gc = () => {
  globalThis.gc();
  globalThis.gc();
};

// --- 0. mechanism sanity: a detached, unreferenced element must be collected
{
  let loose = document.createElement('div');
  const ref = new WeakRef(loose);
  loose = null;
  gc();
  const looseCollected = ref.deref() === undefined;
  console.log('sanity: detached unreferenced element collectible:', looseCollected);
  if (!looseCollected) {
    console.log('gc/WeakRef mechanism not working here; aborting');
    process.exit(2);
  }
}

// --- 1. redraw: old board (with its listeners) collectible while instance is alive
let wrap = document.createElement('div');
document.body.appendChild(wrap);
const cg = Chessground(wrap, {});
let board1 = cg.state.dom.elements.board;
const boardRef = new WeakRef(board1);
cg.redrawAll(); // detaches board1 (renderWrap clears wrap.innerHTML)
board1 = null; // drop test-side reference only
gc();
const boardCollected = boardRef.deref() === undefined;
console.log('old cg-board (with listeners) collectible after redrawAll:', boardCollected);

// --- 2. destroy: wrap subtree collectible (RO disconnected, doc unbind called)
const wrapRef = new WeakRef(wrap);
wrap = null; // drop test-side reference
const roCountAtDestroy = FakeRO.registry.length;
cg.destroy();
cg.destroyRef = undefined;
gc();
const wrapCollected = wrapRef.deref() === undefined;
const roEmptyAfterDestroy = FakeRO.registry.length === 0;
console.log('RO registry size at destroy (expect 1 = no accumulation):', roCountAtDestroy);
console.log('wrap subtree collectible after destroy:', wrapCollected);
console.log('RO registry empty after destroy:', roEmptyAfterDestroy);

// --- 3. control: a live board (in the DOM tree, referenced by state) must NOT be collected
{
  const wrap2 = document.createElement('div');
  document.body.appendChild(wrap2);
  const cg2 = Chessground(wrap2, {});
  let b2 = cg2.state.dom.elements.board;
  const b2Ref = new WeakRef(b2);
  b2 = null;
  gc();
  const b2StillAlive = b2Ref.deref() !== undefined;
  console.log('live board still reachable (control):', b2StillAlive);
  if (!b2StillAlive) {
    console.log('control failed: live board was collected; aborting');
    process.exit(2);
  }
}

if (boardCollected && wrapCollected && roEmptyAfterDestroy && roCountAtDestroy === 1) {
  console.log('OK: no listener-side retention; RO was the only globally-owned handle');
  process.exit(0);
} else {
  console.log('UNEXPECTED retention detected');
  process.exit(1);
}

