// One-off: prove in real Chrome that (a) the old cg-board (with its bindBoard
// listeners) is collectible after redrawAll while the instance is alive, and
// (b) the wrap subtree is collectible after destroy (real ResizeObserver
// controller releases it only via disconnect()).
import { createServer } from 'node:http';
import { readFile, mkdtemp } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import path from 'node:path';
import os from 'node:os';

const ROOT = 'D:/dev/ab-tasks/chessground-qwen-med-r1';
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const PORT = 8472;
const CDP_PORT = 9334;
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };

const failures = [];
const check = (name, ok, detail) => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  [' + detail + ']' : ''}`);
  if (!ok) failures.push(name);
};

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  if (url.pathname === '/favicon.ico') return res.writeHead(204).end?.() ?? res.end();
  const p = path.join(ROOT, decodeURIComponent(url.pathname));
  try {
    const data = await readFile(p);
    res.writeHead(200, { 'content-type': MIME[path.extname(p)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('nf');
  }
});
await new Promise(r => server.listen(PORT, '127.0.0.1', r));

const profile = await mkdtemp(path.join(os.tmpdir(), 'cg-chrome2-'));
const chrome = spawn(
  CHROME,
  [
    '--headless=new',
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-gpu',
    '--js-flags=--expose-gc',
    `--remote-debugging-port=${CDP_PORT}`,
    `--user-data-dir=${profile}`,
    'about:blank',
  ],
  { stdio: 'ignore' },
);
try {
  let up = false;
  for (let i = 0; i < 50 && !up; i++) {
    try {
      await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/version`)).json();
      up = true;
    } catch {
      await sleep(200);
    }
  }
  if (!up) throw new Error('chrome did not start');

  const tab = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/new?about:blank`, { method: 'PUT' })).json();
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((r, j) => {
    ws.onopen = r;
    ws.onerror = () => j(new Error('ws connect failed'));
  });
  let id = 0;
  const pending = new Map();
  ws.onmessage = m => {
    const msg = JSON.parse(m.data);
    if (msg.id) {
      pending.get(msg.id)?.(msg);
      pending.delete(msg.id);
    }
  };
  const send = (method, params = {}) =>
    new Promise(r => {
      const i = ++id;
      pending.set(i, r);
      ws.send(JSON.stringify({ id: i, method, params }));
    });
  const evalJs = async expr => {
    const res = (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result;
    if (res.exceptionDetails) throw new Error(JSON.stringify(res.exceptionDetails));
    return res.result.value;
  };
  const gc = async () => {
    await evalJs(`gc(); gc(); gc(); true`);
    await sleep(50);
  };

  await send('Runtime.enable');
  await send('Page.enable');
  await send('Page.navigate', { url: `http://127.0.0.1:${PORT}/demo.html` });
  await sleep(800);

  // sanity: plain object + detached element mechanics
  check('gc() exposed in page', (await evalJs(`typeof gc === 'function'`)) === 'function');
  check(
